@app.get("/service-worker.js")
def app_service_worker():
    worker = """const CACHE = "mega-ia-2-shell-v3";
self.addEventListener("install", event => event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(["/", "/manifest.webmanifest", "/app-icon-192-v3.png", "/app-icon-512-v3.png"])).then(() => self.skipWaiting())));
self.addEventListener("activate", event => event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(key => key !== CACHE).map(key => caches.delete(key)))).then(() => self.clients.claim())));
self.addEventListener("fetch", event => {
  const request = event.request;
  if (request.method !== "GET" || new URL(request.url).origin !== self.location.origin) return;
  if (request.mode === "navigate") event.respondWith(fetch(request).then(response => { if (response.ok) caches.open(CACHE).then(cache => cache.put("/", response.clone())); return response; }).catch(() => caches.match("/")));
});"""
    return Response(worker, media_type="application/javascript", headers={"Cache-Control": "no-cache", "Service-Worker-Allowed": "/"})

